import React from 'react';
import Header from './components/Header';

function App() {
  return (
    <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-white transition-colors duration-300">
      <Header />
      <main className="container mx-auto px-4 py-8">
        {/* Contenu de votre application */}
        <h1 className="text-4xl font-bold mt-8 text-center">
          Bienvenue sur LuxeDesign
        </h1>
        <p className="text-center text-neutral-600 dark:text-neutral-400 mt-4">
          Un header moderne avec traduction et mode sombre
        </p>
      </main>
    </div>
  );
}

export default App;
